"""Fundus image enhancement used for the definitor input (same steps as the old pipeline):

    1. histogram equalisation of S in HSV   (old: histogram_equalization_hsv_s)
    2. CLAHE on L in LAB, clip 2.0, tile 16x16   (old: apply_clahe_lab)

Improvement over the old code: both statistics are taken only from the retina (pixels brighter
than `black_level`), not from the black border, and the border is kept exactly black afterwards.

Only numpy + OpenCV + PIL: this file can be copied as-is into the ProcessorApplication script
(the executor ships opencv-python 4.9, numpy 1.26) so inference sees exactly what training saw.
"""
import cv2
import numpy as np

DEFAULTS = {'hsv_s': True, 'clahe': True, 'clip_limit': 2.0, 'tile': 16, 'black_level': 10}


def retina_mask(rgb: np.ndarray, black_level: int = 10) -> np.ndarray:
    return cv2.cvtColor(rgb, cv2.COLOR_RGB2GRAY) > black_level


def retina_box(rgb: np.ndarray, black_level: int = 10):
    """(left, top, right, bottom) of the non-black area, right/bottom exclusive; None if all black."""
    ys, xs = np.nonzero(retina_mask(rgb, black_level))
    if not len(xs):
        return None
    return int(xs.min()), int(ys.min()), int(xs.max()) + 1, int(ys.max()) + 1


def _equalize_masked(channel: np.ndarray, mask: np.ndarray) -> np.ndarray:
    """histogram equalisation with the histogram of the masked pixels only"""
    vals = channel[mask]
    if vals.size == 0:
        return channel
    hist = np.bincount(vals.ravel(), minlength=256).astype(np.float64)
    cdf = hist.cumsum()
    nz = cdf[cdf > 0]
    lut = np.clip(np.round((cdf - nz[0]) / max(1.0, cdf[-1] - nz[0]) * 255), 0, 255).astype(np.uint8)
    out = channel.copy()
    out[mask] = lut[channel[mask]]
    return out


def enhance(rgb: np.ndarray, hsv_s=True, clahe=True, clip_limit=2.0, tile=16, black_level=10) -> np.ndarray:
    """uint8 RGB [H, W, 3] -> enhanced uint8 RGB, border black."""
    rgb = np.ascontiguousarray(rgb[..., :3], dtype=np.uint8)
    mask = retina_mask(rgb, black_level)
    out = rgb
    if hsv_s:
        hsv = cv2.cvtColor(out, cv2.COLOR_RGB2HSV)
        hsv[..., 1] = _equalize_masked(hsv[..., 1], mask)
        out = cv2.cvtColor(hsv, cv2.COLOR_HSV2RGB)
    if clahe:
        lab = cv2.cvtColor(out, cv2.COLOR_RGB2LAB)
        lab[..., 0] = cv2.createCLAHE(clipLimit=float(clip_limit), tileGridSize=(int(tile), int(tile))).apply(lab[..., 0])
        out = cv2.cvtColor(lab, cv2.COLOR_LAB2RGB)
    out = out.copy()
    out[~mask] = 0
    return out
